# Let me check if there are any differences in how sieve/factor handle edge cases
# that aren't covered by the observable strings
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# Check if sieve handles None
print("=== None input ===")
for func_name, func in [('sieve', sieve), ('factor', factor)]:
    try:
        result = list(func(None))
        print(f"  {func_name}(None) = {result}")
    except Exception as e:
        print(f"  {func_name}(None) raised {type(e).__name__}: {e}")

# Check if sieve/factor handle infinity
print("\n=== Infinity input ===")
import math
for func_name, func in [('sieve', sieve), ('factor', factor)]:
    try:
        result = list(func(math.inf))
        print(f"  {func_name}(inf) = {result[:5]}... ({len(result)} items)")
    except Exception as e:
        print(f"  {func_name}(inf) raised {type(e).__name__}: {e}")

# Check if sieve/factor handle very small positive numbers
print("\n=== Small positive inputs ===")
for n in [0.5, 0.1, 0.01]:
    for func_name, func in [('sieve', sieve), ('factor', factor)]:
        try:
            result = list(func(n))
            print(f"  {func_name}({n}) = {result}")
        except Exception as e:
            print(f"  {func_name}({n}) raised {type(e).__name__}: {e}")
